/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field SalesCategory.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(SalesLine, SalesCategory))]
internal class GUPPricingAttributeSalesLineSalesCategory extends GUPPricingAttributeSalesLine implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, SalesCategory);
}

public str getRefValue(Str _defaultValue)
{
    EcoResCategory ecoResCategory;
    var recId = str2Int64(_defaultValue);
    select firstonly * from ecoResCategory where ecoResCategory.RecId == recId;
    return ecoResCategory.Name;
}

public void lookupAllowedValues(object _formStringControl)
{
    EcoResCategoryHierarchyRole retailHierarchyRole;
    EcoResCategoryHierarchy retailHierarchy;

    select firstonly CategoryHierarchy from retailHierarchyRole
                where retailHierarchyRole.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::Sales;

    retailHierarchy = EcoResCategoryHierarchy::find(retailHierarchyRole.CategoryHierarchy);

    if (!retailHierarchy)
    {
        // _link.lookupAllowedValues(_formStringControl);
        return;
    }

    container hierarchyRoles = RetailCategoryPriceRule::allowedCategoryHierarchyRoles();

    // Let isMultiHierarchy == true, to make the categorical dropdown box visible.
    EcoResCategoryLookupParameters lookupParameters = new EcoResCategoryLookupParameters();
    lookupParameters.parmMultiRoleSelectionSet(hierarchyRoles);

    Args args = new Args();
    args.name(formStr(EcoResCategorySingleLookup));
    args.caller(_formStringControl);
    args.record(retailHierarchy);
    args.lookupField(fieldNum(EcoResCategory, RecId));
    args.parmObject(lookupParameters);
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
}
